"""Generate the synthetic, Metrica-shaped tracking and event fixtures.

Run from the repository root::

    uv run python tests/fixtures/make_metrica_fixtures.py

The output is a wholly invented two-game match pair. Nothing here is copied from
or derived from Metrica Sports' sample data: every coordinate comes from the
closed-form motion model below plus a seeded PRNG, and the frame numbers, the
substitution moment, the event sequence and the roster are chosen in this file.
What *is* reproduced, deliberately, is the container: the three header rows, the
blank ``_y`` columns, the ``NaN`` spelling, the ``PlayerNN``/``Player NN``
labels and the ``Sample_Game_N_...csv`` filenames that
:mod:`pressing._io` parses. A file format is not match data.

Every structural quirk the loader has to survive is listed in ``QUIRKS`` and
asserted against the generated bytes by ``verify()``, which runs at the end of
``main()``. If a quirk stops being present the generator fails loudly rather
than quietly retiring the regression tests that depend on it.
"""

from __future__ import annotations

import csv
import math
from dataclasses import dataclass, field
from pathlib import Path

import numpy as np

FPS = 25
FIXTURE_ROOT = Path(__file__).resolve().parent / "metrica"
COORD_DECIMALS = 5

#: Structural quirks these fixtures exist to keep exercising. ``verify()``
#: checks each one against the bytes that were just written.
QUIRKS: tuple[str, ...] = (
    "three header rows, data starting on the fourth line",
    "row 0 repeats the team name over each x/y pair, row 1 carries jersey numbers",
    "every named column is followed by a blank one, and the ball is named last",
    "game 2's away file spells one label 'Player 26', with a space",
    "the same 'Player 26' spelling appears in the events From/To columns",
    "bench players occupy full columns that are NaN for the whole file",
    "a substitution where the outgoing and incoming players overlap on one frame",
    "player presence is contiguous within a block, so spans are real spans",
    "the ball has NaN runs while the ball is dead",
    "the ball columns are byte-identical in the home and away files",
    "frames come in non-contiguous blocks, so no velocity may span a block edge",
    "both periods appear in one file, so no velocity may span half time",
    "the two games attack in opposite directions in the first half",
    "players and the ball stray off the pitch, so coordinates leave [0, 1]",
    "an event row with End Frame 0 and NaN start/end coordinates",
    "a BALL LOST whose End X/Y is NaN, forcing the tracked-ball fallback",
    "hyphenated event subtypes that must be split into a token set",
)

# --------------------------------------------------------------------------- #
# Motion model
# --------------------------------------------------------------------------- #

#: Base position of each of the eleven formation slots, in Metrica's normalized
#: top-left frame, for a team attacking towards ``x = 1``. Slot 0 is the
#: goalkeeper. Slot 4 sits deliberately near the touchline so that its
#: oscillation carries it off the pitch, exactly as real tracking does.
FORMATION: tuple[tuple[float, float], ...] = (
    (0.020, 0.500),
    (0.200, 0.160),
    (0.190, 0.380),
    (0.190, 0.620),
    (0.205, 1.000),
    (0.400, 0.180),
    (0.390, 0.420),
    (0.390, 0.580),
    (0.405, 0.830),
    (0.600, 0.400),
    (0.620, 0.600),
)

#: Standard deviation of the per-frame position jitter, in normalized units.
#: 0.0003 x 105 m = 3.2 cm per frame, i.e. about 1.1 m/s of noise at 25 Hz,
#: comfortably below the 12 m/s clip in :func:`pressing._io.compute_velocities`
#: so the fixtures do not lose velocities to the speed guard.
JITTER = 0.0003


def _slot_track(slot: int, frames: np.ndarray, seed: int) -> tuple[np.ndarray, np.ndarray]:
    """Return normalized ``(x, y)`` for one formation slot over ``frames``.

    The path is a pair of slow sinusoids plus a seeded Gaussian jitter, chosen
    so speeds stay in the few-metres-per-second range that real tracking shows.

    Args:
        slot: Formation slot index, 0 to 10, keyed into :data:`FORMATION`.
        frames: Frame numbers to evaluate at, for a team attacking ``x = 1``.
        seed: PRNG seed for the jitter.

    Returns:
        ``(x, y)`` arrays in Metrica's normalized top-left frame.
    """
    base_x, base_y = FORMATION[slot]
    amp_x = 0.030 + 0.006 * (slot % 5)
    amp_y = 0.020 + 0.005 * (slot % 4)
    period_x = 350.0 + 47.0 * slot
    period_y = 410.0 + 61.0 * slot
    phase_x = 0.37 * slot
    phase_y = 1.13 * slot + 0.5

    time = frames.astype(np.float64)
    x = base_x + amp_x * np.sin(2.0 * math.pi * time / period_x + phase_x)
    y = base_y + amp_y * np.sin(2.0 * math.pi * time / period_y + phase_y)

    rng = np.random.default_rng(seed)
    x = x + rng.normal(0.0, JITTER, size=time.size)
    y = y + rng.normal(0.0, JITTER, size=time.size)
    return x, y


def _ball_track(frames: np.ndarray, seed: int) -> tuple[np.ndarray, np.ndarray]:
    """Return the normalized ``(x, y)`` ball path, before any dead-ball holes."""
    time = frames.astype(np.float64)
    x = 0.500 + 0.250 * np.sin(2.0 * math.pi * time / 600.0 + 0.2)
    y = 0.500 + 0.200 * np.sin(2.0 * math.pi * time / 430.0 + 1.0)
    rng = np.random.default_rng(seed)
    x = x + rng.normal(0.0, JITTER, size=time.size)
    y = y + rng.normal(0.0, JITTER, size=time.size)
    return x, y


def _mirror(x: np.ndarray, y: np.ndarray) -> tuple[np.ndarray, np.ndarray]:
    """Rotate a normalized position 180 degrees about the centre spot."""
    return 1.0 - x, 1.0 - y


# --------------------------------------------------------------------------- #
# Match description
# --------------------------------------------------------------------------- #


@dataclass(frozen=True)
class Column:
    """One player column in a tracking file.

    Attributes:
        label: Header label exactly as written, spaces and all.
        jersey: Shirt number written into header row 1.
        slot: Formation slot the player occupies while on the pitch.
        spans: Inclusive frame ranges the player is tracked over. An empty list
            means an unused bench column, NaN for the whole file.
    """

    label: str
    jersey: int
    slot: int
    spans: tuple[tuple[int, int], ...] = ()


@dataclass(frozen=True)
class Game:
    """One synthetic game.

    Attributes:
        number: Game number written into the filenames.
        blocks: ``(period, first_frame, last_frame)`` triples, in order.
        home_attacks_positive: Period to ``True`` when home attacks ``x = 1``
            in Metrica's raw frame during that period.
        home: Home tracking columns, goalkeeper first.
        away: Away tracking columns, goalkeeper first.
        ball_live: Inclusive frame ranges the ball is tracked over.
        events: Raw event rows, minus the coordinates filled in from tracking.
    """

    number: int
    blocks: tuple[tuple[int, int, int], ...]
    home_attacks_positive: dict[int, bool]
    home: tuple[Column, ...]
    away: tuple[Column, ...]
    ball_live: tuple[tuple[int, int], ...]
    events: tuple[tuple[object, ...], ...] = field(default=())


def _starters(
    first: int, keeper: int, spans: tuple[tuple[int, int], ...]
) -> list[Column]:
    """Build eleven starter columns, goalkeeper first, sharing one span list.

    Args:
        first: Shirt number of the first outfield player; the ten outfielders
            take ``first`` to ``first + 9``.
        keeper: Shirt number of the goalkeeper, who is written first.
        spans: Frame ranges every starter is tracked over.

    Returns:
        Eleven columns in header order, slot 0 being the goalkeeper.
    """
    numbers = [keeper, *range(first, first + 10)]
    return [
        Column(f"Player{number}", number, slot, spans)
        for slot, number in enumerate(numbers)
    ]


# Game 1: three blocks, two of them in period 1, plus a substitution.
G1_BLOCKS = ((1, 1, 120), (1, 30001, 30120), (2, 62501, 62620))
G1_FULL = ((1, 120), (30001, 30120), (62501, 62620))
G1_SUB_FRAME = 30060

_G1_HOME_STARTERS = _starters(1, 11, G1_FULL)
# Player1 is substituted off: he stops mid-block 2 and never appears in block 3.
# Player12 comes on at the very frame Player1 goes off, so the two overlap on
# exactly one frame and the incoming player has no previous frame to difference.
_G1_HOME_STARTERS[1] = Column("Player1", 1, 1, ((1, 120), (30001, G1_SUB_FRAME)))

GAME_1 = Game(
    number=1,
    blocks=G1_BLOCKS,
    home_attacks_positive={1: True, 2: False},
    home=(
        *_G1_HOME_STARTERS,
        Column("Player12", 12, 1, ((G1_SUB_FRAME, 30120), (62501, 62620))),
        Column("Player13", 13, 5, ()),
        Column("Player14", 14, 6, ()),
    ),
    away=(
        *_starters(15, 25, G1_FULL),
        Column("Player26", 26, 5, ()),
        Column("Player27", 27, 6, ()),
        Column("Player28", 28, 7, ()),
    ),
    # The ball is only tracked through the opening block; blocks 2 and 3 were
    # cut from a stretch where the ball is not tracked at all.
    ball_live=((1, 120),),
    events=(
        # Team, Type, Subtype, Period, Start Frame, End Frame, From, To
        ("Away", "SET PIECE", "KICK OFF", 1, 1, 0, "Player19", ""),
        ("Away", "PASS", "", 1, 1, 14, "Player19", "Player21"),
        ("Away", "PASS", "", 1, 14, 38, "Player21", "Player15"),
        ("Away", "PASS", "", 1, 52, 73, "Player15", "Player19"),
        ("Away", "PASS", "", 1, 88, 110, "Player19", "Player21"),
    ),
)

# Game 2: two blocks, one per period, and the first half runs the other way.
G2_BLOCKS = ((1, 1, 120), (2, 55001, 55120))
G2_FULL = ((1, 120), (55001, 55120))
G2_KICK_OFF = 41
G2_SECOND_HALF_KICK_OFF = 55041
G2_LOSS_FRAME = 55071

GAME_2 = Game(
    number=2,
    blocks=G2_BLOCKS,
    home_attacks_positive={1: False, 2: True},
    home=(
        *_starters(1, 11, G2_FULL),
        Column("Player12", 12, 5, ()),
        Column("Player13", 13, 6, ()),
        Column("Player14", 14, 7, ()),
    ),
    away=(
        *_starters(15, 25, G2_FULL),
        # The space is the point: game 2 writes this label with one.
        Column("Player 26", 26, 5, ()),
    ),
    # Dead before each kick-off, and dead again the frame after the ball is lost.
    ball_live=((G2_KICK_OFF, 120), (G2_SECOND_HALF_KICK_OFF, G2_LOSS_FRAME)),
    events=(
        ("Away", "SET PIECE", "KICK OFF", 1, G2_KICK_OFF, G2_KICK_OFF, "Player23", "Player 26"),
        ("Away", "PASS", "", 1, G2_KICK_OFF, 79, "Player23", "Player20"),
        (
            "Home", "SET PIECE", "KICK OFF-RETAKEN", 2,
            G2_SECOND_HALF_KICK_OFF, G2_SECOND_HALF_KICK_OFF, "Player5", "",
        ),
        ("Home", "PASS", "", 2, G2_SECOND_HALF_KICK_OFF, 55062, "Player5", "Player4"),
        ("Home", "BALL LOST", "FORCED", 2, G2_LOSS_FRAME, G2_LOSS_FRAME, "Player4", ""),
    ),
)

GAMES = (GAME_1, GAME_2)


# --------------------------------------------------------------------------- #
# Generation
# --------------------------------------------------------------------------- #


def _frames_and_periods(game: Game) -> tuple[np.ndarray, np.ndarray]:
    """Flatten a game's blocks into parallel frame and period arrays."""
    frames: list[int] = []
    periods: list[int] = []
    for period, first, last in game.blocks:
        for frame in range(first, last + 1):
            frames.append(frame)
            periods.append(period)
    return np.array(frames, dtype=np.int64), np.array(periods, dtype=np.int64)


def _in_spans(frames: np.ndarray, spans: tuple[tuple[int, int], ...]) -> np.ndarray:
    """Boolean mask of the frames covered by any of ``spans``."""
    mask = np.zeros(frames.size, dtype=bool)
    for first, last in spans:
        mask |= (frames >= first) & (frames <= last)
    return mask


def _team_tracks(
    game: Game,
    columns: tuple[Column, ...],
    frames: np.ndarray,
    periods: np.ndarray,
    seed_base: int,
    *,
    is_home: bool,
) -> list[tuple[np.ndarray, np.ndarray]]:
    """Build the normalized ``(x, y)`` arrays for one team, holes included.

    :data:`FORMATION` is written for a team attacking ``x = 1``, so a team is
    mirrored whenever it is attacking ``x = 0`` in that frame's period. The two
    teams are always opposite, which is what the direction detector checks.
    """
    mirror = np.array(
        [game.home_attacks_positive[int(period)] is not is_home for period in periods],
        dtype=bool,
    )
    tracks: list[tuple[np.ndarray, np.ndarray]] = []
    for index, column in enumerate(columns):
        x, y = _slot_track(column.slot, frames, seed_base + index)
        flipped_x, flipped_y = _mirror(x, y)
        x = np.where(mirror, flipped_x, x)
        y = np.where(mirror, flipped_y, y)
        live = _in_spans(frames, column.spans)
        x = np.where(live, x, np.nan)
        y = np.where(live, y, np.nan)
        tracks.append((x, y))
    return tracks


def _game_ball(
    game: Game, frames: np.ndarray, periods: np.ndarray
) -> tuple[np.ndarray, np.ndarray]:
    """Build the normalized ball path, with its dead-ball NaN runs punched out."""
    x, y = _ball_track(frames, 9000 + game.number)
    mirror = np.array(
        [not game.home_attacks_positive[int(period)] for period in periods], dtype=bool
    )
    flipped_x, flipped_y = _mirror(x, y)
    x = np.where(mirror, flipped_x, x)
    y = np.where(mirror, flipped_y, y)
    live = _in_spans(frames, game.ball_live)
    return np.where(live, x, np.nan), np.where(live, y, np.nan)


def _cell(value: float) -> str:
    """Format one coordinate the way Metrica's exporter does."""
    if not math.isfinite(value):
        return "NaN"
    return f"{value:.{COORD_DECIMALS}f}"


def _write_tracking(
    path: Path,
    side: str,
    columns: tuple[Column, ...],
    frames: np.ndarray,
    periods: np.ndarray,
    tracks: list[tuple[np.ndarray, np.ndarray]],
    ball: tuple[np.ndarray, np.ndarray],
) -> None:
    """Write one Metrica-shaped tracking CSV, three header rows and all."""
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("w", newline="", encoding="utf-8") as handle:
        writer = csv.writer(handle)
        writer.writerow(["", "", ""] + [c for _ in columns for c in (side, "")] + ["", ""])
        writer.writerow(
            ["", "", ""] + [c for col in columns for c in (str(col.jersey), "")] + ["", ""]
        )
        writer.writerow(
            ["Period", "Frame", "Time [s]"]
            + [c for col in columns for c in (col.label, "")]
            + ["Ball", ""]
        )
        ball_x, ball_y = ball
        for index in range(frames.size):
            row: list[str] = [
                str(int(periods[index])),
                str(int(frames[index])),
                f"{float(frames[index]) / FPS:.2f}",
            ]
            for x, y in tracks:
                row.append(_cell(float(x[index])))
                row.append(_cell(float(y[index])))
            row.append(_cell(float(ball_x[index])))
            row.append(_cell(float(ball_y[index])))
            writer.writerow(row)


EVENT_HEADER = [
    "Team", "Type", "Subtype", "Period", "Start Frame", "Start Time [s]",
    "End Frame", "End Time [s]", "From", "To", "Start X", "Start Y", "End X", "End Y",
]


def _write_events(
    path: Path,
    game: Game,
    frames: np.ndarray,
    ball: tuple[np.ndarray, np.ndarray],
) -> None:
    """Write one Metrica-shaped events CSV.

    Set pieces get NaN coordinates, the opening kick-off of game 1 keeps the
    upstream exporter's End Frame 0, and the game 2 BALL LOST gets a NaN End
    X/Y so the loss locator has to fall back to the tracked ball.
    """
    ball_x, ball_y = ball
    lookup = {int(frame): index for index, frame in enumerate(frames)}

    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("w", newline="", encoding="utf-8") as handle:
        writer = csv.writer(handle)
        writer.writerow(EVENT_HEADER)
        for team, kind, subtype, period, start, end, sender, receiver in game.events:
            start_frame = int(start)
            end_frame = int(end)
            if kind == "SET PIECE":
                start_x = start_y = end_x = end_y = math.nan
            elif kind == "BALL LOST":
                index = lookup[start_frame]
                start_x, start_y = float(ball_x[index]), float(ball_y[index])
                end_x = end_y = math.nan
            else:
                index = lookup[start_frame]
                start_x, start_y = float(ball_x[index]), float(ball_y[index])
                end_index = lookup.get(end_frame, index)
                end_x, end_y = float(ball_x[end_index]), float(ball_y[end_index])
            writer.writerow(
                [
                    team, kind, subtype, period,
                    start_frame, f"{start_frame / FPS:.2f}",
                    end_frame, f"{end_frame / FPS:.2f}",
                    sender, receiver,
                    _round(start_x), _round(start_y), _round(end_x), _round(end_y),
                ]
            )


def _round(value: float) -> str:
    """Format an event coordinate to Metrica's two decimal places."""
    if not math.isfinite(value):
        return "NaN"
    return f"{value:.2f}"


def generate(game: Game, root: Path = FIXTURE_ROOT) -> None:
    """Write all three CSVs for one synthetic game."""
    frames, periods = _frames_and_periods(game)
    ball = _game_ball(game, frames, periods)
    directory = root / f"Sample_Game_{game.number}"
    for side, columns, seed in (
        ("Home", game.home, 1000 * game.number),
        ("Away", game.away, 1000 * game.number + 500),
    ):
        tracks = _team_tracks(
            game, columns, frames, periods, seed, is_home=side == "Home"
        )
        _write_tracking(
            directory / f"Sample_Game_{game.number}_RawTrackingData_{side}_Team.csv",
            side,
            columns,
            frames,
            periods,
            tracks,
            ball,
        )
    _write_events(
        directory / f"Sample_Game_{game.number}_RawEventsData.csv", game, frames, ball
    )


# --------------------------------------------------------------------------- #
# Verification
# --------------------------------------------------------------------------- #


def _read(path: Path) -> list[list[str]]:
    """Read a fixture CSV back as raw cells."""
    with path.open(newline="", encoding="utf-8") as handle:
        return list(csv.reader(handle))


def _spans(present: list[int]) -> list[tuple[int, int]]:
    """Collapse a sorted frame list into inclusive contiguous spans."""
    if not present:
        return []
    out: list[tuple[int, int]] = []
    first = previous = present[0]
    for frame in present[1:]:
        if frame != previous + 1:
            out.append((first, previous))
            first = frame
        previous = frame
    out.append((first, previous))
    return out


def verify(root: Path = FIXTURE_ROOT) -> dict[str, str]:
    """Assert every quirk in :data:`QUIRKS` is present in the written files.

    Args:
        root: Directory holding the ``Sample_Game_N`` folders.

    Returns:
        A quirk to evidence mapping, one entry per :data:`QUIRKS` item.

    Raises:
        AssertionError: When a quirk is missing from the generated fixtures.
    """
    evidence: dict[str, str] = {}
    files = {
        (game.number, side): _read(
            root
            / f"Sample_Game_{game.number}"
            / f"Sample_Game_{game.number}_RawTrackingData_{side}_Team.csv"
        )
        for game in GAMES
        for side in ("Home", "Away")
    }
    events = {
        game.number: _read(
            root / f"Sample_Game_{game.number}" / f"Sample_Game_{game.number}_RawEventsData.csv"
        )
        for game in GAMES
    }

    rows = files[(1, "Home")]
    assert rows[2][:3] == ["Period", "Frame", "Time [s]"]
    assert rows[3][0] == "1" and rows[3][1] == "1"
    evidence[QUIRKS[0]] = f"row 2 = {rows[2][:3]}, row 3 starts {rows[3][:3]}"

    assert rows[0][3] == "Home" and rows[1][3] == "11"
    evidence[QUIRKS[1]] = f"row 0[3]={rows[0][3]!r}, row 1[3]={rows[1][3]!r}"

    names = rows[2]
    assert all(names[i + 1] == "" for i in range(3, len(names) - 1, 2))
    assert names[-2] == "Ball" and names[-1] == ""
    evidence[QUIRKS[2]] = f"{(len(names) - 5) // 2 + 1} named columns, last is {names[-2]!r}"

    away2 = files[(2, "Away")]
    assert "Player 26" in away2[2], "the spaced label is gone"
    evidence[QUIRKS[3]] = f"game 2 away header contains {away2[2][away2[2].index('Player 26')]!r}"

    spaced = [row for row in events[2][1:] if "Player 26" in (row[8], row[9])]
    assert spaced, "no event row carries the spaced label"
    evidence[QUIRKS[4]] = f"{len(spaced)} event row(s) with From/To 'Player 26'"

    def presence(rows: list[list[str]], column: int) -> list[int]:
        return [int(r[1]) for r in rows[3:] if r[column] != "NaN"]

    empty = [
        rows[2][i]
        for i in range(3, len(rows[2]) - 2, 2)
        if not presence(rows, i)
    ]
    assert empty, "no all-NaN bench column survived"
    evidence[QUIRKS[5]] = f"game 1 home all-NaN columns: {empty}"

    out_col = rows[2].index("Player1")
    in_col = rows[2].index("Player12")
    out_frames = set(presence(rows, out_col))
    in_frames = set(presence(rows, in_col))
    overlap = sorted(out_frames & in_frames)
    assert overlap == [G1_SUB_FRAME], f"substitution overlap is {overlap}"
    assert max(out_frames) == G1_SUB_FRAME and min(in_frames) == G1_SUB_FRAME
    evidence[QUIRKS[6]] = f"Player1 and Player12 share exactly frame {overlap[0]}"

    spans_out = _spans(sorted(out_frames))
    spans_in = _spans(sorted(in_frames))
    assert spans_out == [(1, 120), (30001, G1_SUB_FRAME)], spans_out
    assert spans_in == [(G1_SUB_FRAME, 30120), (62501, 62620)], spans_in
    evidence[QUIRKS[7]] = f"Player1 spans {spans_out}, Player12 spans {spans_in}"

    dead_runs: dict[int, list[tuple[int, int]]] = {}
    for game in GAMES:
        home_rows = files[(game.number, "Home")]
        ball_col = len(home_rows[2]) - 2
        dead = [int(r[1]) for r in home_rows[3:] if r[ball_col] == "NaN"]
        assert dead, f"game {game.number} has no dead-ball NaN run"
        dead_runs[game.number] = _spans(dead)
    evidence[QUIRKS[8]] = f"ball NaN runs per game: {dead_runs}"

    for game in GAMES:
        home_rows = files[(game.number, "Home")]
        away_rows = files[(game.number, "Away")]
        assert [r[-2:] for r in home_rows[3:]] == [r[-2:] for r in away_rows[3:]]
    evidence[QUIRKS[9]] = "home and away ball columns match cell for cell in both games"

    blocks = _spans([int(r[1]) for r in rows[3:]])
    assert len(blocks) == 3, blocks
    evidence[QUIRKS[10]] = f"game 1 frame blocks: {blocks}"

    periods = sorted({int(r[0]) for r in rows[3:]})
    assert periods == [1, 2]
    boundary = min(int(r[1]) for r in rows[3:] if r[0] == "2")
    evidence[QUIRKS[11]] = f"periods {periods} in one file, period 2 starts at frame {boundary}"

    def keeper_mean_x(rows: list[list[str]], period: int) -> float:
        values = [float(r[3]) for r in rows[3:] if r[0] == str(period) and r[3] != "NaN"]
        return sum(values) / len(values)

    keepers = {
        (number, side, period): keeper_mean_x(files[(number, side)], period)
        for number in (1, 2)
        for side in ("Home", "Away")
        for period in (1, 2)
    }
    for number in (1, 2):
        for period in (1, 2):
            home_x = keepers[(number, "Home", period)]
            away_x = keepers[(number, "Away", period)]
            assert (home_x < 0.5) is not (away_x < 0.5), (number, period, home_x, away_x)
            other = keepers[(number, "Home", 3 - period)]
            assert (home_x < 0.5) is not (other < 0.5), "no half-time flip"
    assert keepers[(1, "Home", 1)] < 0.5 < keepers[(2, "Home", 1)]
    evidence[QUIRKS[12]] = (
        "home keeper mean normalized x in period 1: "
        f"game 1 {keepers[(1, 'Home', 1)]:.3f}, game 2 {keepers[(2, 'Home', 1)]:.3f}"
    )

    stray: list[float] = []
    for rows_any in files.values():
        for row in rows_any[3:]:
            for cell in row[3:]:
                if cell == "NaN":
                    continue
                value = float(cell)
                if value < 0.0 or value > 1.0:
                    stray.append(value)
    assert stray, "nothing leaves the unit square"
    evidence[QUIRKS[13]] = (
        f"{len(stray)} coordinates outside [0, 1], min {min(stray):.5f}, max {max(stray):.5f}"
    )

    zero_end = [row for row in events[1][1:] if row[6] == "0"]
    assert zero_end, "the End Frame 0 row is gone"
    assert zero_end[0][10] == "NaN" and zero_end[0][12] == "NaN"
    evidence[QUIRKS[14]] = f"game 1 event row with End Frame 0: {zero_end[0][:3]} + NaN coordinates"

    lost = [row for row in events[2][1:] if row[1] == "BALL LOST"]
    assert lost and lost[0][12] == "NaN" and lost[0][13] == "NaN"
    assert lost[0][10] != "NaN"
    evidence[QUIRKS[15]] = (
        f"game 2 BALL LOST at frame {lost[0][4]} has End X/Y NaN but Start X/Y "
        f"({lost[0][10]}, {lost[0][11]})"
    )

    hyphenated = [row[2] for row in events[2][1:] if "-" in row[2]]
    assert hyphenated, "no hyphenated subtype"
    evidence[QUIRKS[16]] = f"hyphenated subtypes: {hyphenated}"

    missing = [quirk for quirk in QUIRKS if not evidence.get(quirk)]
    assert not missing, f"unverified quirks: {missing}"
    return evidence


def main() -> None:
    """Regenerate every fixture, then prove the quirks survived."""
    for game in GAMES:
        generate(game)
    for quirk, proof in verify().items():
        print(f"OK  {quirk}\n    {proof}")


if __name__ == "__main__":
    main()
